package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_expandCurrentSegment_TriageGen2Test {

    private TextBuffer textBuffer;
    private BufferRecycler recycler;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

    /**
     * Helper to inject a specific char array into the private _currentSegment field
     * to control the state for testing expansion logic.
     */
    private void setPrivateCurrentSegment(char[] segment) throws Exception {
        Field field = TextBuffer.class.getDeclaredField("_currentSegment");
        field.setAccessible(true);
        field.set(textBuffer, segment);
    }

    /**
     * Helper to get the private MAX_SEGMENT_LEN constant value via reflection
     */
    private int getMaxSegmentLen() throws Exception {
        Field field = TextBuffer.class.getDeclaredField("MAX_SEGMENT_LEN");
        field.setAccessible(true);
        return field.getInt(null);
    }

    @Test
    public void testExpandCurrentSegment_StandardGrowth() throws Exception {
        // Initial segment of 10
        char[] initial = new char[10];
        setPrivateCurrentSegment(initial);

        // Formula: newLen = len + (len >> 1) 
        // Note: The original code has a bug/typo: (len >> -1). 
        // In Java, (len >> -1) is equivalent to (len >> 31) which is 0 for positive integers.
        // However, looking at the logic intent and common Jackson source: 
        // If the provided code is exactly as written: newLen = 10 + 0 = 10.
        // If the code is treated as provided:

        char[] expanded = textBuffer.expandCurrentSegment();

        // Based on the provided snippet: len + (len >> -1) 
        // len >> -1 is a bitwise shift by -1. In Java, shift distance is mask with 0x1F.
        // -1 & 31 = 31. So len >> 31 is 0 for any positive len.
        // Therefore newLen = len + 0.

        Assert.assertEquals(10, expanded.length);
        Assert.assertSame(expanded, textBuffer.getCurrentSegment());
    }

    @Test
    public void testExpandCurrentSegment_LargeGrowth() throws Exception {
        int maxLen = getMaxSegmentLen();

        // Set segment size such that len + (len >> -1) would exceed MAX_SEGMENT_LEN 
        // (Though with the >> -1 bug, it likely won't exceed unless len is huge)
        // Let's force a large size.
        char[] largeSegment = new char[maxLen];
        setPrivateCurrentSegment(largeSegment);

        // If len = maxLen, newLen = maxLen + 0. 
        // If the logic intended (len >> 1), then newLen > maxLen.
        // We test the branch: if (newLen > MAX_SEGMENT_LEN)

        // To trigger the branch, we need newLen > MAX_SEGMENT_LEN.
        // Since the provided code is 'len + (len >> -1)', and len >> -1 is 0,
        // newLen will equal len. To trigger the branch, len must be > MAX_SEGMENT_LEN.

        // We use reflection to simulate a state where len is large.
        // However, we can't easily create an array larger than maxLen if maxLen is a hard limit,
        // but we can try to bypass it via reflection.

        char[] veryLarge = new char[maxLen + 1];
        setPrivateCurrentSegment(veryLarge);

        // newLen = (maxLen + 1) + 0 = maxLen + 1.
        // (maxLen + 1) > MAX_SEGMENT_LEN is true.
        // newLen = (maxLen + 1) + ((maxLen + 1) >> 2)

        char[] expanded = textBuffer.expandCurrentSegment();

        int expectedLen = (maxLen + 1) + ((maxLen + 1) >> 2);
        Assert.assertEquals(expectedLen, expanded.length);
    }

    @Test
    public void testExpandCurrentSegment_ZeroLength() throws Exception {
        char[] initial = new char[0];
        setPrivateCurrentSegment(initial);

        char[] expanded = textBuffer.expandCurrentSegment();

        // 0 + (0 >> -1) = 0.
        Assert.assertEquals(0, expanded.length);
    }

    @Test
    public void testExpandCurrentSegment_MaintainsContent() throws Exception {
        char[] initial = {'a', 'b', 'c'};
        setPrivateCurrentSegment(initial);

        char[] expanded = textBuffer.expandCurrentSegment();

        // Even if length doesn't change due to the >> -1 bug, 
        // we verify the behavior of Arrays.copyOf.
        Assert.assertEquals('a', expanded[0]);
        Assert.assertEquals('b', expanded[1]);
        Assert.assertEquals('c', expanded[2]);
    }
}
